  2	
  3	declare(strict_types=1);
  4	
  5	namespace DBHelper\Exception;
  6	
  7	use AppUtils\ConvertHelper\JSONConverter;
  8	use AppUtils\Interfaces\RenderableInterface;
  9	use AppUtils\StringBuilder;
 10	use AppUtils\Traits\RenderableTrait;
 11	use DBHelper;
 12	use PDOException;
 13	
 14	abstract class BaseErrorRenderer implements RenderableInterface
 15	{
 16	    use RenderableTrait;
 17	
 18	    protected StringBuilder $message;
 19	    protected ?PDOException $exception;
 20	
 21	    public function __construct(?PDOException $exception, ?string $message)
 22	    {
 23	        $this->exception = $exception;
 24	        $this->message = sb();
 25	
 26	        if(empty($message)) {
 27	            $message = DBHelper::getErrorMessage();
 28	        }
 29	
 30	        if(empty($message)) {
 31	            $message = $this->getEmptyMessageText();
 32	        }
 33	
 34	        $this->line($message);
 35	
 36	        $this->line('Database: '.$this->resolveConnectionInfo());
 37	
 38	        if(isset($this->exception)) {
 39	            $this->line('PDO exception type: '.get_class($this->exception));
 40	            $this->line('PDO message: '.$this->exception->getMessage());
 41	        }
 42	
 43	        $query = DBHelper::getActiveQuery();
 44	
 45	        if($query !== null)
 46	        {
 47	            $this->dumpSQL();
 48	            $this->analyzeQuery($query[0], $query[1]);
 49	        }
 50	    }
 51	
 52	    private function resolveConnectionInfo(): string
 53	    {
 54	        try
 55	        {
 56	            $db = DBHelper::getSelectedDB();
 57	            return $db['username'] . '@' . $db['name'] . ' on ' . $db['host'];
 58	        }
 59	        catch(\Throwable $e)
 60	        {
 61	            // Fallback to boot-time constants if no DB is selected yet
 62	            return APP_DB_USER . '@' . APP_DB_NAME . ' on ' . APP_DB_HOST;
 63	        }
 64	    }
 65	
 66	    private function dumpSQL() : void
 67	    {
 68	        $this->nl();
 69	        $this->line('SQL (with simulated variable values):');
 70	        $this->line($this->renderSQL());
 71	    }
 72	
 73	    abstract protected function renderSQL() : string;
 74	
 75	    abstract public function getEmptyMessageText() : string;
 76	
 77	    abstract protected function nl() : self;
 78	
 79	    abstract protected function line(string $content) : self;
 80	
 81	    abstract protected function styleError(string $text) : string;
 82	
 83	    private function analyzeQuery(string $sql, array $values) : void
 84	    {
 85	        $this->nl();
 86	        $this->line('Query placeholders:');
 87	
 88	        // retrieve a list of all placeholders used in the query
 89	        $params = array();
 90	        $paramNames = array();
 91	        preg_match_all('/[:]([a-zA-Z0-9_]+)/', $sql, $params, PREG_PATTERN_ORDER);
 92	
 93	        if(isset($params[1][0])) {
 94	            $paramNames = array_unique($params[1]);
 95	        }
 96	
 97	        $tokens = array();
 98	        $errors = false;
 99	        foreach($paramNames as $name)
100	        {

101	            $foundName = null;
102	            if(array_key_exists($name, $values)) {
103	                $foundName = $name;
104	            }
105	
106	            if(array_key_exists(':'.$name, $values)) {
107	                $foundName = ':'.$name;
108	            }
109	
110	            if($foundName) {
111	                $tokenInfo = JSONConverter::var2json($values[$foundName], JSON_THROW_ON_ERROR);
112	            } else {
113	                $errors = true;
114	                $tokenInfo = $this->styleError('Placeholder has not been specified in the value list');
115	            }
116	
117	            $tokens[] = $name . ' = ' . $tokenInfo;
118	        }
119	
120	        foreach($values as $name => $value) {
121	            if(!in_array(ltrim($name, ':'), $paramNames, true)) {
122	                $errors = true;
123	                $tokens[] = $name . ' = '.$this->styleError('No matching placeholder found in the query');
124	            }
125	        }
126	
127	        if(!$errors) {
128	            $this->line('NOTE: Placeholders have inconsistencies.');
129	        }
130	
131	        foreach($tokens as $token) {
132	            $this->line($token);
133	        }
134	    }
135	
136	    public function render(): string
137	    {
138	        return (string)$this->message;
139	    }
140	}

51	
52	    /**
53	     * Resolves the active database connection info as a human-readable string
54	     * in the form <code>username@name on host</code>.
55	     *
56	     * The primary path calls {@see DBHelper::getSelectedDB()} so that the
57	     * correct database is reported even when a non-default database (e.g. the
58	     * test database) is selected at the time of the error.
59	     *
60	     * If {@see DBHelper::getSelectedDB()} throws — which can happen during
61	     * early boot before any database has been selected — the method falls back
62	     * to the boot-time constants <code>APP_DB_USER</code>,
63	     * <code>APP_DB_NAME</code>, and <code>APP_DB_HOST</code>.
64	     * <code>\Throwable</code> is caught (rather than a narrower type) to guard
65	     * against both <code>DBHelper_Exception</code> and any unexpected
66	     * <code>Error</code> subclass that could surface inside the try block.
67	     *
68	     * @return string Connection info string, e.g. <code>app_user@mydb on localhost</code>.
69	     */
70	    private function resolveConnectionInfo(): string
71	    {
72	        try
73	        {
74	            $db = DBHelper::getSelectedDB();
75	            return $db['username'] . '@' . $db['name'] . ' on ' . $db['host'];
76	        }
77	        catch(\Throwable $e)
78	        {
79	            // Fallback to boot-time constants if no DB is selected yet
80	            return APP_DB_USER . '@' . APP_DB_NAME . ' on ' . APP_DB_HOST;
81	        }
82	    }
83	
84	    private function dumpSQL() : void
85	    {
86	        $this->nl();
87	        $this->line('SQL (with simulated variable values):');
88	        $this->line($this->renderSQL());
89	    }
90	
91	    abstract protected function renderSQL() : string;
92	
93	    abstract public function getEmptyMessageText() : string;
94	
95	    abstract protected function nl() : self;

